<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { Download, FilePenLine, Save, WandSparkles } from 'lucide-vue-next'
import Pager from '../components/Pager.vue'
import { api, downloadMarkdown, isArchived, localDate, messageOf, notify, projectName, query, ui } from '../api'
import type { Page, Worklog } from '../types'
const props=defineProps<{revision:number}>();const emit=defineEmits<{changed:[]}>()
const logs=ref<Worklog[]>([]),total=ref(0),offset=ref(0),loading=ref(false),error=ref(''),saving=ref(false),generating=ref(false),draft=ref(false),dirty=ref(false),editing=ref<Worklog>();const limit=20
const generator=reactive({project_id:'',period_type:'day' as 'day'|'week',date:localDate()});const form=reactive({project_id:'',period_type:'day' as 'day'|'week',log_date:'',content:''});const readonly=computed(()=>isArchived(form.project_id))
async function load(){loading.value=true;try{const data=await api<Page<Worklog>>(`/api/worklogs?${query({limit,offset:offset.value})}`);logs.value=data.items;total.value=data.total}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
onMounted(load);watch(()=>props.revision,load)
function canReplace(){return !dirty.value||window.confirm('当前草稿尚未保存，确定切换并放弃本次修改？')}
async function generate(){if(!canReplace())return;generating.value=true;error.value='';try{const data=await api<{project_id:string;period_type:'day'|'week';log_date:string;content:string}>('/api/worklogs/generate',{method:'POST',body:JSON.stringify(generator)});Object.assign(form,data);editing.value=undefined;draft.value=true;dirty.value=true;notify('草稿已生成，请核对内容后保存')}catch(e){error.value=messageOf(e)}finally{generating.value=false}}
function select(log:Worklog){if(!canReplace())return;editing.value=log;Object.assign(form,{project_id:log.project_id,period_type:log.period_type,log_date:log.log_date,content:log.content});draft.value=true;dirty.value=false;error.value=''}
async function save(){if(!form.content.trim()||saving.value||readonly.value)return;saving.value=true;error.value='';try{const saved=await api<Worklog>(editing.value?`/api/worklogs/${editing.value.id}`:'/api/worklogs',{method:editing.value?'PATCH':'POST',body:JSON.stringify({project_id:form.project_id,period_type:form.period_type,log_date:form.log_date,content:form.content,...(editing.value?{version:editing.value.version}:{})})});editing.value=saved;dirty.value=false;notify('工作日志已保存');emit('changed');await load()}catch(e){error.value=messageOf(e)}finally{saving.value=false}}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload));onUnmounted(()=>window.removeEventListener('beforeunload',beforeUnload))
defineExpose({canLeave:canReplace})
function download(){downloadMarkdown(form.content,`${form.log_date}-${form.period_type==='week'?'周报':'日报'}.md`)}
function page(next:number){offset.value=next;void load()}
</script>
<template><div class="page-heading"><div><h1>工作日志</h1><p class="page-description">从实际记录生成草稿，整理成自己的日报和周报。</p></div></div><div class="generator-bar"><div><WandSparkles :size="19"/><strong>生成一份日志</strong></div><label class="sr-only" for="log-project">日志范围</label><select id="log-project" v-model="generator.project_id"><option value="">全部项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><label class="sr-only" for="log-period">日志周期</label><select id="log-period" v-model="generator.period_type"><option value="day">日报</option><option value="week">周报</option></select><label class="sr-only" for="log-date">日志日期</label><input id="log-date" v-model="generator.date" type="date" required/><button class="button primary" :disabled="generating||!generator.date" @click="generate">{{generating?'正在生成…':'生成草稿'}}</button></div><p class="input-hint generator-hint">只生成草稿，保存前可以自由编辑；已有同日期、同项目的日志不会被覆盖。</p><div v-if="error" class="error-banner" role="alert">{{error}}</div><div class="worklog-layout"><aside class="surface saved-logs"><div class="section-heading"><h2>已保存 <span class="count">{{total}}</span></h2></div><p v-if="loading" class="loading-message">正在读取…</p><div v-else-if="!logs.length" class="empty-state compact"><FilePenLine :size="30"/><p>保存后的日志会放在这里，方便查阅和再次编辑。</p></div><div v-else class="log-list"><button v-for="log in logs" :key="log.id" :class="{selected:editing?.id===log.id}" @click="select(log)"><span class="log-date">{{log.log_date}}<span class="badge">{{log.period_type==='week'?'周报':'日报'}}</span></span><span>{{log.project_id?projectName(log.project_id):'全部项目'}}</span></button></div><Pager :offset="offset" :limit="limit" :total="total" @change="page"/></aside><section class="surface log-editor"><template v-if="draft"><div class="section-heading"><div><h2>{{form.log_date}} {{form.period_type==='week'?'周报':'日报'}}<span v-if="dirty" class="draft-label">未保存</span></h2><p class="input-hint">{{form.project_id?projectName(form.project_id):'全部项目'}}<span v-if="readonly"> · 已归档，只读</span></p></div><div class="row-actions"><button class="button subtle small" :disabled="!form.content" @click="download"><Download :size="15"/>导出 Markdown</button><button v-if="!readonly" class="button primary small" :disabled="saving||!form.content.trim()" @click="save"><Save :size="15"/>{{saving?'正在保存…':'保存日志'}}</button></div></div><label class="sr-only" for="worklog-content">日志正文，Markdown 格式</label><textarea id="worklog-content" v-model="form.content" :readonly="readonly" class="markdown-editor" spellcheck="false" @input="dirty=true"/><div class="editor-footer">Markdown 格式<span>{{form.content.length}} 字</span></div></template><div v-else class="empty-state editor-empty"><FilePenLine :size="40"/><h2>把今天的工作整理成文</h2><p>选择项目与日期后生成草稿，或从左侧打开已保存的日志。</p></div></section></div></template>
